code.java:
class Solution {
    public int numberOfEmployeesWhoMetTarget(int[] hours,int target){
        int answer=0;
        for(int value:hours)if(value>=target)answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun numberOfEmployeesWhoMetTarget(hours:IntArray,target:Int):Int{
        return hours.count{
            it>=target
        }
    }
}

code.cpp:
class Solution {
    public:int numberOfEmployeesWhoMetTarget(vector<int>& hours,int target){
        return count_if(hours.begin(),hours.end(),[&](int value){
            return value>=target;
        });
    }
};
